import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(g):
    H=len(g); W=len(g[0])
    cnt=Counter(v for r in g for v in r); bg=cnt.most_common(1)[0][0]
    sep=[i for i,r in enumerate(g) if len(set(r))==1 and r[0]!=bg]
    # bands exclude separator rows
    bb=[]; st=0
    for y in sep+[H]:
        bb.append((st,y-1)); st=y+1
    def var(rows): return any(len(set(r))>1 for r in rows)
    src=None; sb=None
    for i,b in enumerate(bb):
        s=[g[r][:] for r in range(b[0],b[1]+1)]
        if var(s): src=s; sb=i
    o=[]
    for i,(s0,e0) in enumerate(bb):
        if i==sb: o+=g[s0:e0+1]
        else: o+=src[:]
        if i<len(sep)-1: o.append([g[y][0] for y in [y]] ) 
    return o
print(f(G['Demo pair 1 input']))

